<?php
function flow_form($action,$i,$label,$fields=null,$photo=false){$f=flow_state($i['id']);?><form method="post" <?=$photo?'enctype="multipart/form-data"':''?> data-confirm="Save this workflow decision?" class="flow-form"><?php csrf();?><input type="hidden" name="action" value="<?=e($action)?>"><input type="hidden" name="issue_id" value="<?=(int)$i['id']?>"><input type="hidden" name="flow_version" value="<?=(int)$f['version']?>"><input type="hidden" name="location_snapshot" value="<?=e(flow_location_hash($i))?>"><?php if($fields)$fields();?><label>Reason / note<textarea name="note" minlength="5" maxlength="2000" required></textarea></label><?php if($photo):?><label>New evidence photo<input type="file" name="reopen_photo" accept="image/jpeg,image/png,image/webp" required></label><?php endif;?><button class="button secondary"><?=e($label)?></button></form><?php }
function flow_panel($i){
$boundary=followup_location_result($i);$f=flow_state($i['id']);$role=user()['role'];$admin=$role==='admin';$officer=$role==='officer'&&(int)$i['officer_id']===(int)user()['id'];$team=$role==='maintenance'&&(int)$i['maintenance_id']===(int)user()['id'];$staff=$admin||$officer||$team;$active=in_array($i['status'],['Assigned','In Progress'],true);$owner=(int)$i['user_id']===(int)user()['id'];
?><section class="panel section-space flow-panel" id="workflow"><h2>Workflow controls</h2><p>Location: <?=flow_location_ready($i)?'Reviewed against pin':($f['location_state']==='flagged'?'Correction required':'Review required')?> · Stage: <?=e($i['status']==='Awaiting Approval'?'Province Admin final approval':($i['maintenance_stage']==='Review'?'District Officer completion review':($i['maintenance_stage']?:$i['status'])))?></p>
<?php if($boundary['outside'])echo '<p class="alert warning">Pin outside configured '.e(implode(', ',$boundary['outside'])).' boundary. Correction required.</p>';elseif($boundary['configured'])echo '<p class="small muted">Configured boundary checks passed. Human location review is still required.</p>';if($f['location_note']&&($staff||$owner))echo '<p class="small">Location review: '.e($f['location_note']).'</p>';if($admin&&!in_array($i['status'],['Resolved','Rejected','Duplicate'],true)&&!$i['duplicate_of']):?><details><summary>Check location and routing</summary><p class="small muted">Compare the pin, address and selected Province / District / Town. Human review is required. Any configured admin-supplied boundaries are checked as well. Flag mismatches; System Admin can correct routing.</p><?php flow_form('flow_location',$i,'Save location review',function(){?><label>Result<select name="location_state"><option value="reviewed">Map pin and selected area checked</option><option value="flagged">Mismatch / correction required</option></select></label><?php });?></details><?php endif;
if($officer&&$active&&(int)$f['accepted_by']!==(int)user()['id'])flow_form('flow_accept',$i,'Accept District Officer responsibility');
elseif($staff&&$f['accepted_at'])echo '<p class="small muted">Officer acceptance: '.e($f['accepted_at']).'</p>';
if($team&&$active&&$i['maintenance_stage']==='In Progress'):?><details><summary>Work blocked / waiting</summary><p class="small muted">Blocking does not extend the due date automatically.</p><?php flow_form('flow_block',$i,'Report blocker',function(){?><label>Type<select name="block_kind"><option>Materials</option><option>Access</option><option>External agency</option><option>Other</option></select></label><label>Next review<input type="date" name="next_review" min="<?=date('Y-m-d')?>" required></label><?php });?></details><?php endif;
if($i['maintenance_stage']==='Blocked'):?><p>Blocked: <?=e($f['block_kind'])?> · Review: <?=e($f['next_review'])?></p><?php if($staff){echo '<p>'.e($f['block_reason']).'</p>';if($team||$officer)flow_form('flow_resume',$i,'Resume work');}endif;
if($i['maintenance_stage']==='Officer Return'):?><p class="alert warning">Province Admin returned completion to the District Officer. The team must wait for officer instructions.</p><?php if($officer)flow_form('flow_return_team',$i,'Return to current team for more work');endif;
if($owner||$staff):?><div id="reopen-report"><?php
if($f['reopen_state']==='rejected'&&$i['status']==='Resolved'):
 $review=q("SELECT message FROM issue_events WHERE issue_id=? AND kind='reopen_review' ORDER BY id DESC LIMIT 1",[$i['id']])->fetchColumn();
 $reason=preg_replace('/^Province Admin rejected reopening\. /','',(string)$review);
 ?><p class="alert warning">Reopen request declined. The report remains resolved.</p><?php if($reason!==''):?><p><?=e($reason)?></p><?php endif;
endif;
if($f['reopen_state']==='pending'):?><p class="alert warning">Reopen request awaiting Province Admin review. Report remains Resolved until accepted.</p><?php if($owner||$staff)echo '<p>'.e($f['reopen_reason']).'</p>';endif;
if($i['status']==='Resolved'&&($owner||$admin)&&$f['reopen_state']!=='pending'):?><div><h3>Request reopening</h3><p>Provide a reason and new photo. Province Admin review is required.</p><?php flow_form('reopen',$i,'Submit reopen request',null,true);?></div><?php endif;
if($admin&&$f['reopen_state']==='pending'&&$i['status']==='Resolved'){if($f['reopen_photo'])echo '<img class="upload-preview" src="media.php?file='.e($f['reopen_photo']).'" alt="Reopen evidence">';flow_form('flow_reopen_review',$i,'Review reopen request',function(){?><label>Decision<select name="decision"><option value="accepted">Accept — return to initial review</option><option value="rejected">Reject — keep resolved</option></select></label><?php });}
?></div><?php endif;
if($staff):?><details><summary>Staff-only operational notes</summary><p class="small muted">Only staff permitted to access this report can read these notes. Public updates belong in Progress & conversation.</p><?php foreach(geo_raw('SELECT n.message,n.created_at,u.name FROM issue_internal_notes n JOIN users u ON u.id=n.user_id WHERE n.issue_id=? ORDER BY n.id DESC LIMIT 20',[$i['id']])->fetchAll() as $n):?><article class="flow-private-note"><strong><?=e($n['name'])?></strong><small><?=e($n['created_at'])?></small><p><?=e($n['message'])?></p></article><?php endforeach;flow_form('flow_internal_note',$i,'Save staff-only note');?></details><?php endif;?></section><?php
}
